var waves = [];
var wavesNum = 15;

var yoff = 0.0;
var themeColor;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  themeColor = random(360);
  for (let i = 0; i < wavesNum; i++) {
    waves.push(new Wave(i));
  }
}

function draw() {
  push();
  colorMode(RGB, 255, 255, 255);
  background(255);
  pop();

  for (let i = 0; i < waves.length; i++) {
    waves[i].display();
  }

  fill(255);
  stroke(0);
  strokeWeight(3);
  beginShape();
  vertex(0, 0);
  vertex(width, 0);
  vertex(width, height);
  vertex(0, height);

  beginContour();
  let xoff = 0.0;

  for (let x = 0; x < width; x += 0.5) {
    vertex(x, map(noise(xoff, yoff), 0, 1, height, 0));
    xoff += 0.005;
  }

  for (let x = width; x > 0; x -= 0.5) {
    vertex(x, map(noise(xoff, yoff), 0, 1, 0, height));
    xoff += 0.005;
  }

  endContour();

  yoff += 0.05;

  endShape(CLOSE);
}

function Wave(index) {
  this.tmpHue = themeColor;
  this.hue = index % 2 == 0 ? this.tmpHue : (this.tmpHue + 180) % 360;
  this.saturation = random(30, 100);
  this.brightness = random(80, 100);
  this.x = random(-width / 2, width / 2);
  this.yoff = random(10.00);
  this.yoffDelta = random(0.01, 0.05);
  this.xoffDelta = random(0.005, 0.02);
  this.vertexDeltaA = floor(random(1, 6));
  this.vertexDeltaB = floor(random(1, 6));

  this.display = function () {
    push();
    translate(this.x, 0);
    noStroke();
    fill(this.hue, this.saturation, this.brightness);
    beginShape();
    var xoff = 0.0;
    for (let y = 0; y < height; y += (Math.max(0.001, Math.abs(this.vertexDeltaA)) || 1)) {
      curveVertex(map(noise(xoff, this.yoff), 0, 1, 0, width), y);
      xoff += this.xoffDelta;
    }

    for (let y = height; y > 0; y -= this.vertexDeltaB) {
      curveVertex(map(noise(xoff, this.yoff), 0, 1, 0, width), y);
      xoff += this.xoffDelta;
    }

    endShape();
    pop();

    this.yoff += this.yoffDelta;
  }
}
